6. public class BillingTests
7. {
8.     [Fact]
9.     public void Invoice_NoTier_ComputesTotalAndQuote()
10.     {
11.         var processor = new OrderProcessor();
12.         var lines = new[]
13.         {
14.             new OrderLine("A", 50m, 1),
15.             new OrderLine("B", 20m, 2),
16.         };
17. 
18.         var invoice = processor.DoStuff(lines, "none");
19. 
20.         // subtotal = 90, shipping = 9.99 (subtotal < 100)
21.         // total = 90 * 1.08 = 97.20
22.         // quote = (90 + 9.99) * 1.08 = 107.9892 -> 107.99
23.         Assert.Equal(97.20m, invoice.Total);
24.         Assert.Equal(107.99m, invoice.Quote);
25.         Assert.Equal(9.99m, invoice.Shipping);
26.     }
27. 
28.     [Fact]
29.     public void Invoice_Gold_AppliesDiscountAndFreeShipping()
30.     {
31.         var processor = new OrderProcessor();
32.         var lines = new[] { new OrderLine("A", 100m, 2) };
33. 
34.         var invoice = processor.DoStuff(lines, "gold");
35. 
36.         // subtotal = 200, shipping = 0 (subtotal >= 100)
37.         // discounted = 200 * 0.90 = 180, total = 180 * 1.08 = 194.40
38.         // quote base = 200 -> same as total = 194.40
39.         Assert.Equal(194.40m, invoice.Total);
40.         Assert.Equal(194.40m, invoice.Quote);
41.         Assert.Equal(0m, invoice.Shipping);
42.     }
43. 
44.     [Fact]
45.     public void Invoice_Silver_AppliesFivePercentDiscount()
46.     {
47.         var processor = new OrderProcessor();
48.         var lines = new[] { new OrderLine("A", 200m, 1) };
49. 
50.         var invoice = processor.DoStuff(lines, "silver");
51. 
52.         // subtotal = 200, shipping = 0
53.         // discounted = 200 * 0.95 = 190, total = 190 * 1.08 = 205.20
54.         Assert.Equal(205.20m, invoice.Total);
55.         Assert.Equal(205.20m, invoice.Quote);
56.     }
57. 
58.     [Fact]
59.     public void Tax_Wrapper_MatchesUnderlyingRule()
60.     {
61.         Assert.Equal(TaxRules.Apply(100m), LegacyTax.ApplyTaxWrapper(100m));
62.         Assert.Equal(108m, LegacyTax.ApplyTaxWrapper(100m));
63.     }
